127:    /** 3. 模式与目录：模式切换监听、目录/开关变更监听、GUI 状态恢复与初始一致性。 */
128:    void installModeAndFolders() {
129:        // 模式切换：互斥由 modeToggleGroup 承担，点击已选按钮可取消回到"未选择"态；
130:        //    不清空另一模式参数：GUI 状态与已确认缓存按模式隔离保留
131:        refs.modeToggleGroup().selectedToggleProperty().addListener((_, _, _) -> mc.onModeChanged());
132:
133:        // 目录/开关变更：刷新列表 + 持久化 GUI 状态
134:        refs.inputFolderField().textProperty().addListener((_, _, _) -> mc.onInputFolderChanged());
135:        refs.outputFolderField().textProperty().addListener((_, _, _) -> mc.saveGuiState());
136:        refs.extractCheckedOnlyCheck().selectedProperty().addListener((_, _, _) -> mc.saveGuiState());
137:        refs.openFolderAfterCompleteCheck().selectedProperty().addListener((_, _, _) -> mc.saveGuiState());
138:
139:        // 恢复 GUI 状态（无状态文件时与旧版启动逻辑一致）
140:        mc.restoreGuiState();
141:
142:        // 初始状态一致性（无状态文件时：两个模式都未选中，全部禁用）
143:        mc.updateModeUi();
144:        mc.updateFileCount();
145:        mc.updateListButtons();
146:    }
147:
148:    /** 4. 预览会话缓存：启动扫孤儿 + 10 GiB 台阶提醒 hook + 关窗清空处理器挂接。 */
149:    void installPreviewCacheHooks() {
150:        // 预览会话缓存（需求 2 会话 9）：启动扫孤儿（P7 崩溃恢复）；
151:        //    关窗清空处理器经 scene/window 装配后挂接（initialize 阶段 scene 尚未存在，App.start 稍后装配）
152:        mc.previewCacheLifecycle.startupCleanup();
153:        // 会话 12：磁盘占用提醒 hook（写盘成功且跨 10GiB 台阶时经 checkSizeAlert 触发；
154:        // 在预览后台线程同步回调，这里换算 GiB 文案后回 FX 线程非模态弹窗）
155:        mc.previewCacheLifecycle.setSizeAlertHook(mc::onSizeAlertStep);
156:        refs.fileListView().sceneProperty().addListener((_, _, newScene) -> {
157:            if (newScene == null) {
158:                return;
159:            }
160:            newScene.windowProperty().addListener((_, _, newW) -> {
161:                if (newW instanceof Stage stage) {
162:                    stage.setOnCloseRequest(mc::onWindowCloseRequest);
163:                }
164:            });
165:        });
166:    }
167:
168:    /** 5. 日志区欢迎语（延后一帧，等日志 appender 就位）。 */
169:    void installWelcomeLog() {
170:        Platform.runLater(() -> {
171:            refs.logTextArea().appendText(Texts.get("preview.welcome"));
172:            refs.logTextArea().appendText(Texts.get("preview.welcomeHint"));
173:        });
174:    }
175:}

